/**
* Project: Vanguard Agent
* Function: Autonomous CNN Trend & Headline Generator
* Core Stack: Node.js (ESM) + Official Bright Data JavaScript SDK + Cheerio
*
* IMPORTANT: CNN's own robots.txt disallows /search (Disallow: /search),
* so Bright Data's Web Unlocker refuses it in immediate-access mode -
* that's not a bug, it's the site opting out of that specific path for
* compliant bots. Instead, this hits CNN's own News Sitemap
* (https://www.cnn.com/sitemap/news.xml), which robots.txt explicitly
* lists as a Sitemap: entry - meaning it's meant to be fetched by bots.
* It contains real headline titles and real publish timestamps for the
* last ~48 hours of coverage across every section, which is arguably a
* better fit for "trend monitoring" than a search page anyway.
*/
import fs from 'fs';
import readline from 'readline';
import * as cheerio from 'cheerio';
import { bdclient } from '@brightdata/sdk';
const REPORT_FILE = 'vanguard_trend_report.md';
const CNN_NEWS_SITEMAP = 'https://www.cnn.com/sitemap/news.xml';
// Key comes ONLY from the environment - no hardcoded fallback, ever.
// If a real key has been pasted into a file, a chat, or a log at any
// point, treat it as compromised and rotate it in your Bright Data
// dashboard immediately, even after removing it from the code.
const BRIGHTDATA_KEY = process.env.BRIGHTDATA_API_KEY || '';
if (!BRIGHTDATA_KEY) {
    console.error(
        "\n❌ [Vanguard Config Error] BRIGHTDATA_API_KEY is not set.\n" +
        "   Run it like this instead:\n\n" +
        "   PowerShell:   $env:BRIGHTDATA_API_KEY=\"your_actual_key\"; node vanguard.mjs\n" +
        "   cmd.exe:      set BRIGHTDATA_API_KEY=your_actual_key && node vanguard.mjs\n" +
        "   macOS/Linux:  BRIGHTDATA_API_KEY=your_actual_key node vanguard.mjs\n"
    );
    process.exit(1);
}
// CNN article URLs follow /YYYY/MM/DD/category/slug - used here purely to
// derive a topic category for the breakdown, not for date (the sitemap
// gives us a real publish timestamp directly).
const CNN_ARTICLE_PATTERN = /^\/(\d{4})\/(\d{2})\/(\d{2})\/([a-z0-9-]+)\//i;
const printDashboardHeader = () => {
    console.clear();
    console.log("\x1b[38;5;39m%s\x1b[0m", " ┌────────────────────────────────────────────────────────┐");
    console.log("\x1b[38;5;39m%s\x1b[0m", " │   VANGUARD INTELLIGENCE SERVICE // CNN TREND ENGINE     │");
    console.log("\x1b[38;5;39m%s\x1b[0m", " └────────────────────────────────────────────────────────┘");
};
const promptUser = (queryMessage) => {
    const interfaceInstance = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });
    return new Promise((resolve) => {
        interfaceInstance.question(queryMessage, (inputAnswer) => {
            interfaceInstance.close();
            resolve(inputAnswer.trim());
        });
    });
};
function escapeRegExp(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function categoryFromUrl(loc) {
    try {
        const path = new URL(loc).pathname;
        const dated = path.match(CNN_ARTICLE_PATTERN);
        if (dated) return dated[4].replace(/-/g, ' ');
        // Some CNN URLs skip the date prefix entirely (e.g. video pages
        // like /politics/video/slug). Fall back to the first path segment
        // instead of dumping everything into "uncategorized".
        const segment = path.split('/').filter(Boolean)[0];
        return segment ? segment.replace(/-/g, ' ') : 'uncategorized';
    } catch {
        return 'uncategorized';
    }
}
async function deployVanguardService() {
    printDashboardHeader();
    console.log("\x1b[38;5;244m%s\x1b[0m", "\n [CONFIGURE INTELLIGENCE FILTER]");
    const searchQuery = await promptUser('🔍 Enter a keyword to filter recent CNN headlines (e.g., startup, election, climate): ');
    if (!searchQuery) {
        console.error("\n❌ [Vanguard Error] Input token context empty. Pipeline aborted.");
        return;
    }
    printDashboardHeader();
    console.log(`\n\x1b[38;5;214m🤖 [Vanguard]: Connecting to proxy fabric for target: ${CNN_NEWS_SITEMAP}\x1b[0m`);
    console.log("🤖 [Vanguard]: Initializing automated browser emulation...");
    const client = new bdclient({ apiKey: BRIGHTDATA_KEY });
    try {
        // dataFormat: 'html' returns the raw response body as-is, which
        // works fine for XML too - we just parse it with cheerio's XML
        // mode below instead of treating it as an HTML page.
        const xmlResponse = await client.scrapeUrl(CNN_NEWS_SITEMAP, {
            zone: 'web_unlocker1',
            dataFormat: 'html',
            country: 'us'
        });
        console.log(`\x1b[38;5;46m🤖 [Vanguard]: Data stream ingestion complete. Length: ${xmlResponse.length} bytes.\x1b[0m`);        if (!xmlResponse || xmlResponse.length < 500) {            const preview = xmlResponse ? xmlResponse.slice(0, 300) : '(empty response)';            throw new Error(                `Target returned only ${xmlResponse ? xmlResponse.length : 0} bytes - this is too small to be ` +                `a real sitemap. Raw response below:\n\n${preview}\n\n` +                `Checklist:\n` +                `  1. Confirm BRIGHTDATA_API_KEY is a valid, active key.\n` +                `  2. Confirm 'web_unlocker1' matches an active Web Unlocker zone name in your ` +                `Bright Data dashboard - zone names are account-specific.\n` +                `  3. If the text above mentions a block/captcha, retry in a moment or try a ` +                `different 'country' value.`            );        }        console.log("🤖 [Vanguard]: Processing resilient extraction analytics...");        // xmlMode: true keeps namespaced tags (e.g. news:title) intact        // instead of cheerio's default HTML-parsing/lowercasing behavior.
        const $ = cheerio.load(xmlResponse, { xmlMode: true });
        const insights = [];
        $('url').each((_, el) => {
            const loc = $(el).find('loc').first().text().trim();
            const title = $(el).find('news\\:title').first().text().trim();
            const pubDateRaw = $(el).find('news\\:publication_date').first().text().trim()
                || $(el).find('lastmod').first().text().trim();
            if (!loc || !title) return; // skip entries without a real headline (e.g. galleries/video-only)
            insights.push({
                title: title.replace(/\s+/g, ' '),
                date: pubDateRaw ? pubDateRaw.slice(0, 10) : 'unknown',
                category: categoryFromUrl(loc),
                postUrl: loc
            });
        });
        const uniqueRawInsights = Array.from(new Map(insights.map(item => [item.postUrl, item])).values());
        // Sort newest first using the sitemap's own publish timestamp.        uniqueRawInsights.sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));        // Whole-word match, not substring - plain .includes() would match        // "war" inside "Warner" or "warrant", which are false positives        // for a search on "war". \b enforces a real word boundary.        const keywordPattern = new RegExp(`\\b${escapeRegExp(searchQuery)}\\b`, 'i');        let filteredInsights = uniqueRawInsights.filter(item => keywordPattern.test(item.title));        // Phase 2: fallback to the newest overall headlines if no direct match        let isFallbackMode = false;        if (filteredInsights.length === 0) {            filteredInsights = uniqueRawInsights;            isFallbackMode = true;        }        const uniqueInsights = filteredInsights.slice(0, 10);        if (uniqueInsights.length === 0) {            throw new Error('Zero real headline entries isolated inside the sitemap buffer.');        }        const categoryCounts = uniqueRawInsights.reduce((acc, item) => {            acc[item.category] = (acc[item.category] || 0) + 1;
            return acc;
        }, {});
        const topCategories = Object.entries(categoryCounts)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 5);
        console.log("\n\x1b[38;5;51m┌────────────────────────────────────────────────────────────────────────┐");
        console.log(`│ ► VANGUARD INTELLIGENCE STREAM // CNN // '${searchQuery}'`.padEnd(76, ' ') + '│');
        console.log("└────────────────────────────────────────────────────────────────────────┘\x1b[0m");
        if (isFallbackMode) {
            console.log(`\x1b[33m ⚠️ [Notice] No direct matches for '${searchQuery}'. Showing newest CNN headlines instead.\x1b[0m\n`);
        }
        uniqueInsights.forEach((item, index) => {
            console.log(` \x1b[38;5;46m[${String(index + 1).padStart(2, '0')}]\x1b[0m \x1b[1m${item.title.substring(0, 75)}\x1b[0m`);
            console.log(`     ├─ Category : ${item.category}`);
            console.log(`     ├─ Date     : ${item.date}`);
            console.log(`     └─ Link     : \x1b[38;5;39m\x1b[4m${item.postUrl}\x1b[0m\n`);
        });
        console.log("\x1b[38;5;51m└────────────────────────────────────────────────────────────────────────┘\x1b[0m");
        console.log('\x1b[38;5;244m📊 Top categories in this result set:\x1b[0m');
        topCategories.forEach(([cat, count]) => console.log(`   • ${cat} (${count})`));
        const markdownReport = [
            `# Vanguard CNN Intelligence Digest`,
            `* **Search Keyword:** \`${searchQuery}\``,
            `* **Source:** CNN News Sitemap (robots.txt-approved)`,
            `* **Data Capture Status:** ${isFallbackMode ? 'Newest-headlines fallback' : 'Direct keyword match'}`,
            `* **Timestamp:** ${new Date().toISOString()}`,
            `\n## Top Categories`,
            ...topCategories.map(([cat, count]) => `* **${cat}** - ${count} article(s)`),
            `\n## Headlines`,
            ...uniqueInsights.map((p, idx) =>
                `### ${idx + 1}. ${p.title}\n* **Date:** ${p.date}\n* **Category:** ${p.category}\n* **Link:** [${p.postUrl}](${p.postUrl})`
            )
        ].join('\n');
        fs.writeFileSync(REPORT_FILE, markdownReport, 'utf8');
        console.log(`\x1b[38;5;46m💾 [Vanguard] System Report written successfully -> ${REPORT_FILE}\x1b[0m\n`);
    } catch (pipelineException) {
        console.error("\n❌ [Vanguard Fatal]: Operational routine aborted.");
        console.error(`Reason: ${pipelineException.message}`);
    } finally {
        await client.close();
    }
}
deployVanguardService();
